using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Windows.Forms;
class ContentEditorTests {
 static void Assert(bool value,string reason){if(!value)throw new Exception(reason);}
 static string Fixture="{\"id\":1,\"chapter\":\"Bab A\",\"subChapter\":\"Sub A\",\"namaContent\":\"Satu\",\"description\":\"Lama\",\"type\":[\"CustomType\"],\"scenario\":[{\"id\":0,\"prev_id\":[],\"next_id\":[],\"commands\":\"Begin\",\"parameterscript\":null}],\"scenarioobject\":[],\"unknown\":{\"big\":1234567890123456789,\"text\":\"{ } , [ ] \\\" x\"}}";
 static void ImportTests(){
  var serializer=new JavaScriptSerializer();var doc=new ContentDocument(Fixture+","+Fixture.Replace("\"id\":1,","\"id\":2,"));var current=doc.Item(0);string neighbor=doc.Raw(1),metadata=doc.FieldRaw(0,"description"),unknown=doc.FieldRaw(0,"unknown");
  string legacy="{\"AsbunName\":\"Imported name\",\"skenario\":{\"Items\":[{\"id\":44,\"prev_id\":[],\"next_id\":[],\"commands\":\"First\",\"parameterscript\":\"\",\"event_name\":\"First\"}]}}";
  string objectText="{\"Items\":[{\"objectId\":7,\"GameObjectName\":\"Imported object\",\"ActionsAvailable\":[]}]}";
  string editor=serializer.Serialize(new Dictionary<string,object>{{"ListOfObjects",objectText}});
  var edits=ScenarioImport.Prepare(legacy,editor,current,true,false);Assert(!edits.ContainsKey("type"),"Type replaced without permission");doc.Patch(0,edits);Assert(doc.Raw(1)==neighbor,"Import modified neighbor");Assert(doc.FieldRaw(0,"description")==metadata&&doc.FieldRaw(0,"unknown")==unknown,"Import modified metadata/unknown");Assert(doc.FieldRaw(0,"namaContent")=="\"Satu\"","Imported name replaced metadata");Assert(doc.FieldRaw(0,"scenario").Contains("Begin"),"Import failed normalization");Assert(Convert.ToInt32(((Dictionary<string,object>)((object[])serializer.DeserializeObject(doc.FieldRaw(0,"scenarioobject")))[0])["GameObjectID"])==7,"Imported objects not mapped");Assert(edits["scenario"].Contains(Environment.NewLine+"  {"),"Imported scenario is not indented");Assert(edits["scenario"].Contains("\"prev_id\": []"),"Empty arrays not compact");
  var only=ScenarioImport.Prepare(legacy,null,current,false,false);Assert(only.Count==1&&only.ContainsKey("scenario"),"Scenario-only import scope");
  bool rejected=false;try{ScenarioImport.Prepare(legacy,null,current,true,false);}catch(Exception){rejected=true;}Assert(rejected,"Missing editor accepted for object replacement");
  var converted=ScenarioImport.Prepare(Fixture,null,current,true,true);Assert(converted.ContainsKey("scenarioobject")&&converted.ContainsKey("type"),"Converted JSON import failed");
  string path=Path.Combine(Path.GetTempPath(),"ImportTest-"+Guid.NewGuid().ToString("N")+".json"),content=path+".content.json",editorPath=path+".editor";File.WriteAllText(path,legacy);File.WriteAllText(content,Fixture+","+Fixture.Replace("\"id\":1,","\"id\":2,"));File.WriteAllText(editorPath,editor);
  try{using(var dialog=new ScenarioImportDialog("1")){var drop=typeof(ScenarioImportDialog).GetMethod("DropFiles",BindingFlags.Instance|BindingFlags.NonPublic);drop.Invoke(dialog,new object[]{new[]{editorPath,path}});Assert(dialog.JsonPath==path&&dialog.EditorPath==editorPath,"Pair drop routing failed");drop.Invoke(dialog,new object[]{new[]{path}});Assert(dialog.EditorPath==editorPath,"Single JSON cleared editor");bool rejectedDrop=false;try{drop.Invoke(dialog,new object[]{new[]{path,path}});}catch(TargetInvocationException){rejectedDrop=true;}Assert(rejectedDrop&&dialog.JsonPath==path&&dialog.EditorPath==editorPath,"Invalid drop changed file inputs");Assert(dialog.AllowDrop,"Dialog drop disabled");dialog.Show();Application.DoEvents();dialog.Close();}using(var form=new ContentEditorForm(content)){var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(ContentEditorForm).GetMethod("StageImport",flags).Invoke(form,new object[]{path,editorPath,true,false});var staged=(ContentDocument)typeof(ContentEditorForm).GetField("document",flags).GetValue(form);Assert(staged.FieldRaw(0,"scenarioobject")=="[]","Import applied before confirmation");typeof(ContentEditorForm).GetMethod("ApplySelected",flags).Invoke(form,null);Assert(staged.Raw(1)==Fixture.Replace("\"id\":1,","\"id\":2,"),"UI import changed neighbor");Assert(staged.FieldRaw(0,"scenarioobject").Contains("Imported object"),"UI import did not apply objects");typeof(ContentEditorForm).GetField("dirty",flags).SetValue(form,false);}}finally{File.Delete(path);File.Delete(content);File.Delete(editorPath);}
  Console.WriteLine("PASS import: legacy JSON + string-encoded editor, converted JSON, scenario-only scope, optional objects/type, staged apply and neighbor preservation.");
 }
 [STAThread] static int Main(string[] args){try{string tricky="[{\"parameterscript\":\"{\\\"Text\\\":\\\"a, b: [ ] { }\\\"}\",\"value\":1234567890123456789,\"empty\":[]}]";string formatted=ContentDocument.FormatJson(tricky);Assert(new JavaScriptSerializer().Serialize(new JavaScriptSerializer().DeserializeObject(tricky))==new JavaScriptSerializer().Serialize(new JavaScriptSerializer().DeserializeObject(formatted)),"Formatting changed data");Assert(formatted.Contains("a, b: [ ] { }"),"Formatting changed embedded string");Assert(ContentDocument.FormatJson(formatted)==formatted,"Formatter is not stable");ImportTests();
  string second=Fixture.Replace("\"id\":1,","\"id\":2,").Replace("Satu","Dua");
  var doc=new ContentDocument(Fixture+",\r\n"+second);Assert(doc.Count==2&&doc.IsSequence,"Sequence detection");string original=doc.Text;
  Assert(doc.Search("id","2").SequenceEqual(new[]{1}),"ID search");Assert(doc.Search("chapter","bab a").Count==2,"Chapter insensitive search");Assert(doc.Search("subChapter","Sub A").Count==2,"Subchapter search");Assert(doc.Search("namaContent","Dua").SequenceEqual(new[]{1}),"Name search");Assert(doc.Search("all","missing").Count==0,"Empty results");
  var emptyEdits=new Dictionary<string,string>();doc.Patch(0,emptyEdits);Assert(doc.Text==original,"No-op changes source");
  string beforeScenario=doc.FieldRaw(0,"scenario"),unknown=doc.FieldRaw(0,"unknown");doc.Patch(0,new Dictionary<string,string>{{"description",ContentDocument.Encode("Baru\nParagraf 2")}});
  Assert(doc.Raw(1)==second,"Unselected content changed");Assert(doc.FieldRaw(0,"scenario")==beforeScenario,"Metadata changed scenario");Assert(doc.FieldRaw(0,"unknown")==unknown,"Unknown field changed");Assert(doc.FieldRaw(0,"type")=="[\"CustomType\"]","Type changed");
  string description=doc.FieldRaw(0,"description");doc.Patch(0,new Dictionary<string,string>{{"scenario",beforeScenario.Replace("Begin","CustomCommand")}});Assert(doc.FieldRaw(0,"description")==description,"Scenario changed description");Assert(doc.Raw(1)==second,"Scenario changed neighbor");
  string beforeInvalid=doc.Text;try{doc.Patch(0,new Dictionary<string,string>{{"scenario","{}"}});throw new Exception("Invalid scenario accepted");}catch(FormatException){}Assert(doc.Text==beforeInvalid,"Failed edit mutated document");
  var wrapped=new ContentDocument(doc.Export(true));Assert(wrapped.IsArray&&wrapped.Count==2,"Standard export");var single=new ContentDocument(Fixture);Assert(single.Export(false)==Fixture,"Single no-op");
  string sample=args.Length>0?args[0]:null;if(sample!=null){var real=new ContentDocument(File.ReadAllText(sample));Assert(real.Count>=2,"Sample multi-content");var untouched=Enumerable.Range(0,real.Count).Select(real.Raw).ToArray();real.Patch(real.Count-1,new Dictionary<string,string>{{"namaContent",ContentDocument.Encode("Nama pengujian")}});for(int i=0;i<real.Count-1;i++)Assert(real.Raw(i)==untouched[i],"Sample neighbor changed: "+i);Console.WriteLine("PASS sample: "+real.Count+" content; unselected content preserved exactly.");}
  string temp=Path.Combine(Path.GetTempPath(),"ScenarioConverterTest-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(temp,original);
  try{using(var form=new ContentEditorForm(temp)){form.Show();Application.DoEvents();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var search=(TextBox)typeof(ContentEditorForm).GetField("search",flags).GetValue(form);var by=(ComboBox)typeof(ContentEditorForm).GetField("searchBy",flags).GetValue(form);by.SelectedIndex=4;search.Text="Dua";typeof(ContentEditorForm).GetMethod("Filter",flags).Invoke(form,null);var grid=(DataGridView)typeof(ContentEditorForm).GetField("grid",flags).GetValue(form);Assert(grid.Rows.Count==1,"UI filtering");Assert((int)typeof(ContentEditorForm).GetField("selected",flags).GetValue(form)==1,"UI selection index");var fields=(Dictionary<string,TextBox>)typeof(ContentEditorForm).GetField("fields",flags).GetValue(form);fields["description"].Text="Edit UI";typeof(ContentEditorForm).GetMethod("ApplySelected",flags).Invoke(form,null);var uiDoc=(ContentDocument)typeof(ContentEditorForm).GetField("document",flags).GetValue(form);Assert(uiDoc.Raw(0)==Fixture,"UI modified neighbor");Assert((string)uiDoc.Item(1)["description"]=="Edit UI","UI edit not applied");typeof(ContentEditorForm).GetField("dirty",flags).SetValue(form,false);form.Close();}}finally{File.Delete(temp);}
  Console.WriteLine("PASS: search, targeted metadata/scenario editing, unknown fields, invalid edit atomicity, sequence/array/single formats, no-op and UI startup.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
